+use App\Tests\Support\Catalog;
+use App\Tests\Support\TestDatabase;
+use Doctrine\DBAL\Connection;
+use PHPUnit\Framework\Attributes\CoversClass;
+use PHPUnit\Framework\Attributes\Test;
+use Symfony\Bundle\FrameworkBundle\Test\KernelTestCase;
+
+#[CoversClass(CancelOrderHandler::class)]
+final class CancelOrderHandlerTest extends KernelTestCase
+{
+    protected function setUp(): void
+    {
+        TestDatabase::reset();
+        self::bootKernel();
+        Catalog::seed(self::getContainer()->get(Connection::class));
+    }
+
+    #[Test]
+    public function cancelsOrderAndReturnsStock(): void
+    {
+        $orders = self::getContainer()->get(OrderRepository::class);
+        $stockItems = self::getContainer()->get(StockItemRepository::class);
+        $keyboard = ProductId::fromString(Catalog::KEYBOARD);
+
+        $order = Order::place(OrderId::generate(), CustomerId::generate());
+        $order->addItem($keyboard, 3, new Money(500_00, Currency::CZK));
+        $orders->save($order);
+        self::assertSame(7, $stockItems->get($keyboard)->available());
+
+        self::getContainer()->get(CancelOrderHandler::class)(new CancelOrder($order->id, 'customer request'));
+
+        self::assertSame(OrderStatus::Cancelled, $orders->get($order->id)->status);
+        self::assertSame(10, $stockItems->get($keyboard)->available());
+    }
+
+    #[Test]
+    public function shippedOrderCannotBeCancelled(): void
+    {
+        $orders = self::getContainer()->get(OrderRepository::class);
+        $order = Order::place(OrderId::generate(), CustomerId::generate());
+        $order->addItem(ProductId::fromString(Catalog::KEYBOARD), 1, new Money(500_00, Currency::CZK));
+        $order->confirm();
+        $order->markPaid();
+        $order->ship();
+        $orders->save($order);
+
+        $this->expectException(InvalidOrderStateTransitionException::class);
+        self::getContainer()->get(CancelOrderHandler::class)(new CancelOrder($order->id, ''));
+    }
+}
